from __future__ import annotations

import ast
import io
import re
import tokenize
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent
SOURCE_FILES = sorted((REPO_ROOT / "src").rglob("*.py"))
PROSE_FILES = [REPO_ROOT / "README.md", REPO_ROOT / "Makefile"]

FORBIDDEN = [
    "reproduction of",
    "based on the paper",
    "re-implementation",
    "following the authors",
    "as described by",
    "generated by",
    "ai-assisted",
    "skeleton",
    "placeholder",
    "todo from paper",
    "comprehensive",
    "state-of-the-art",
    "cutting-edge",
    "seamlessly",
    "leveraging",
    "utilize",
    "delve",
    "holistic",
    "meticulously",
    "it's worth noting",
    "in conclusion",
]

EMOJI = re.compile(
    "[\U0001f000-\U0001faff\U00002600-\U000027bf\U00002b00-\U00002bff\U0001f1e6-\U0001f1ff]"
)


def test_source_has_no_comments() -> None:
    offenders: list[str] = []
    for path in SOURCE_FILES:
        text = path.read_text()
        for token in tokenize.generate_tokens(io.StringIO(text).readline):
            if token.type == tokenize.COMMENT:
                offenders.append(f"{path.name}:{token.start[0]}")
    assert not offenders, f"unexpected comments: {offenders}"


def test_source_has_no_docstrings() -> None:
    offenders: list[str] = []
    for path in SOURCE_FILES:
        tree = ast.parse(path.read_text())
        for node in ast.walk(tree):
            if (
                isinstance(node, ast.Module | ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef)
                and ast.get_docstring(node) is not None
            ):
                offenders.append(f"{path.name}:{getattr(node, 'name', 'module')}")
    assert not offenders, f"unexpected docstrings: {offenders}"


def test_no_forbidden_phrases_or_emoji() -> None:
    targets = [*SOURCE_FILES, *(p for p in PROSE_FILES if p.exists())]
    for path in targets:
        lowered = path.read_text().lower()
        for phrase in FORBIDDEN:
            assert phrase not in lowered, f"forbidden phrase {phrase!r} in {path.name}"
        assert not EMOJI.search(path.read_text()), f"emoji in {path.name}"
